import java.util.*;

public class Main {
    public static void main(String[] args) {
        // Before generics: a raw list accepts anything.
        List raw = new ArrayList();
        raw.add(42);                       // compiles, only a warning
        try {
            String s = (String) raw.get(0); // fails only at runtime
            System.out.println(s);
        } catch (ClassCastException e) {
            System.out.println("raw list: ClassCastException at runtime");
        }

        // After generics: the compiler rejects the bad add.
        List<String> names = new ArrayList<>();
        // names.add(42);                  // compile error: int cannot be String
        names.add("Ada");
        String first = names.get(0);       // no cast needed
        System.out.println("typed list: " + names + " first=" + first);

        // One algorithm for every type.
        List<Integer> nums = new ArrayList<>(List.of(3, 1, 2));
        Collections.sort(nums);
        Collections.sort(names);
        System.out.println("sorted nums: " + nums);
    }
}

import java.util.*;

public class Main {
    // T is the type parameter.
    static class Box<T> {
        private final T value;
        Box(T value) { this.value = value; }
        T get() { return value; }
    }

    public static void main(String[] args) {
        // Box<String> is a parameterized type, String the type argument.
        Box<String> a = new Box<>("hi");       // diamond: String is inferred
        System.out.println("Box<String> holds: " + a.get());

        Box raw = new Box("legacy");           // raw type: no checking
        Object o = raw.get();                  // only Object is known
        System.out.println("raw Box holds: " + o);

        // Diamond with var has no target type, so T becomes Object.
        var b = new Box<>("text");             // inferred from the argument here
        System.out.println("var + argument: " + b.get().getClass().getSimpleName());
        List<String> list = new ArrayList<>();  // diamond infers String from target
        var list2 = new ArrayList<>();          // no target: ArrayList<Object>
        list2.add(1);
        list2.add("any");
        System.out.println("var list2 accepts anything: " + list2 + " / " + list);
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        // Arrays are covariant but checked at runtime.
        Object[] objs = new String[1];
        try {
            objs[0] = 42;                       // compiles, fails at runtime
        } catch (ArrayStoreException e) {
            System.out.println("array: ArrayStoreException " + e.getMessage());
        }

        // Generics are invariant: this would not compile.
        List<Integer> ints = new ArrayList<>(List.of(1, 2));
        // List<Number> nums = ints;            // compile error
        // Wildcard gives safe read-only flexibility.
        List<? extends Number> view = ints;
        Number n = view.get(0);                 // reading is fine
        // view.add(2.5);                       // compile error: cannot add
        System.out.println("read from view: " + n + ", list=" + view);

        double total = 0;
        for (Number x : view) total += x.doubleValue();
        System.out.println("sum = " + total);
    }
}

import java.util.*;

public class Main {
    // src PRODUCES T (extends), dest CONSUMES T (super).
    static <T> void copy(List<? super T> dest, List<? extends T> src) {
        for (T t : src) dest.add(t);
    }

    public static void main(String[] args) {
        List<Integer> ints = List.of(1, 2, 3);
        List<Number> numbers = new ArrayList<>();
        List<Object> objects = new ArrayList<>();

        copy(numbers, ints);                    // Integer into List<Number>
        copy(objects, ints);                    // Integer into List<Object>
        System.out.println("ints    = " + ints);
        System.out.println("numbers = " + numbers);
        System.out.println("objects = " + objects);

        // One Comparator<Number> sorts Integer and Double lists (? super E).
        Comparator<Number> byValue = Comparator.comparingDouble(Number::doubleValue);
        List<Integer> a = new ArrayList<>(List.of(3, 1, 2));
        List<Double> b = new ArrayList<>(List.of(2.5, 0.5));
        a.sort(byValue);
        b.sort(byValue);
        System.out.println("sorted ints = " + a + ", doubles = " + b);
    }
}

import java.util.*;

public class Main {
    static int countAny(List<?> list) { return list.size(); }  // reads only

    @SuppressWarnings({"rawtypes", "unchecked"})
    public static void main(String[] args) {
        List<String> strings = new ArrayList<>(List.of("a", "b"));

        List raw = strings;                     // raw alias turns checking off
        raw.add(99);                            // heap pollution, only a warning
        System.out.println("raw accepted an Integer: " + raw);

        List<Object> objs = new ArrayList<>();
        objs.add("anything"); objs.add(1);
        // List<Object> o2 = strings;           // compile error: invariance
        System.out.println("List<Object>: " + objs);

        List<?> unknown = new ArrayList<>(List.of(1, 2, 3));
        Object first = unknown.get(0);          // read as Object
        unknown.add(null);                      // only null can be added
        // unknown.add(5);                      // compile error
        System.out.println("List<?> first=" + first + ", size=" + countAny(unknown));
        unknown.clear();                        // clear/remove are allowed
        System.out.println("after clear: " + unknown);
    }
}

