public class Main {
    static class Factory<T> {
        private final Supplier<T> maker;
        Factory(Supplier<T> maker) { this.maker = maker; }
        T make() { return maker.get(); }        // new T() is impossible, so pass a Supplier
        T[] makeArray(int n, IntFunction<T[]> arr) { return arr.apply(n); }
    }

    public static void main(String[] args) {
        // Erasure: one class serves every parameterization.
        List<String> s = new ArrayList<>();
        List<Integer> i = new ArrayList<>();
        System.out.println("same class: " + (s.getClass() == i.getClass()));

        // instanceof List<String> would not compile; only the raw class is known.
        Object o = s;
        System.out.println("instanceof List<?>: " + (o instanceof List<?>));

        Factory<StringBuilder> f = new Factory<>(StringBuilder::new);
        StringBuilder sb = f.make().append("made");
        System.out.println(sb);
        String[] arr = new Factory<String>(() -> "x").makeArray(3, String[]::new);
        System.out.println("array length " + arr.length + ", type " + arr.getClass().getSimpleName());

        // Casts inserted by javac: the bad element fails at the read site.
        List raw = s;
        raw.add(7);
        try {
            String bad = s.get(0);              // hidden checkcast
        } catch (ClassCastException e) {
            System.out.println("ClassCastException on a line with no visible cast");
        }
    }
}

import java.util.*;

public class Main {
    // T links the input collection and the return value, so a type parameter is needed.
    static <T extends Comparable<? super T>> T max(Collection<? extends T> c) {
        Iterator<? extends T> it = c.iterator();
        T best = it.next();
        while (it.hasNext()) {
            T x = it.next();
            if (x.compareTo(best) > 0) best = x;   // bound unlocks compareTo
        }
        return best;
    }

    // Type appears once and we only read: a wildcard is enough.
    static double sum(Collection<? extends Number> c) {
        double s = 0;
        for (Number n : c) s += n.doubleValue();
        return s;
    }

    public static void main(String[] args) {
        List<Integer> ints = List.of(4, 9, 2);
        List<String> words = List.of("pear", "apple", "zebra");
        System.out.println("max ints  = " + max(ints));
        System.out.println("max words = " + max(words));
        System.out.println("sum ints  = " + sum(ints));
        System.out.println("sum mixed = " + sum(List.of(1, 2.5, 3L)));
    }
}

import java.util.*;

public class Main {
    static class Fruit implements Comparable<Fruit> {
        final int weight;
        Fruit(int w) { weight = w; }
        public int compareTo(Fruit o) { return Integer.compare(weight, o.weight); }
        public String toString() { return getClass().getSimpleName() + "(" + weight + ")"; }
    }
    static class Apple extends Fruit { Apple(int w) { super(w); } }

    // Strict version: T must be Comparable<T> itself.
    static <T extends Comparable<T>> T strictMax(Collection<T> c) {
        return Collections.max(c);
    }
    // JDK-style version.
    static <T extends Object & Comparable<? super T>> T looseMax(Collection<? extends T> c) {
        Iterator<? extends T> it = c.iterator();
        T best = it.next();
        while (it.hasNext()) { T x = it.next(); if (x.compareTo(best) > 0) best = x; }
        return best;
    }

    public static void main(String[] args) throws Exception {
        List<Apple> apples = List.of(new Apple(120), new Apple(180), new Apple(150));
        // strictMax(apples);               // compile error: Apple is not Comparable<Apple>
        Fruit heaviest = looseMax(apples);  // works: Comparable<Fruit> is a super type
        System.out.println("heaviest apple: " + heaviest);

        // Erased signature uses the first bound (Object), matching pre-Java-5 binaries.
        var m = Collections.class.getMethod("max", Collection.class);
        System.out.println("erased return type of Collections.max: " + m.getReturnType().getSimpleName());
    }
}

import java.lang.reflect.Method;
import java.util.*;

public class Main {
    static class Node<T> {
        T data;
        void setData(T d) { data = d; }
    }
    static class IntNode extends Node<Integer> {
        @Override
        void setData(Integer d) { System.out.println("IntNode.setData " + d); data = d; }
    }

    public static void main(String[] args) {
        // javac generated setData(Object) in IntNode as a bridge.
        List<String> found = new ArrayList<>();
        for (Method m : IntNode.class.getDeclaredMethods()) {
            found.add(m.getName() + "(" + m.getParameterTypes()[0].getSimpleName()
                + ") bridge=" + m.isBridge() + " synthetic=" + m.isSynthetic());
        }
        Collections.sort(found);
        found.forEach(System.out::println);

        Node<Integer> n = new IntNode();
        n.setData(5);                          // calls the bridge, which casts and forwards

        Node raw = n;
        try {
            raw.setData("oops");               // bridge's cast to Integer fails
        } catch (ClassCastException e) {
            System.out.println("ClassCastException inside the bridge");
        }
    }
}

import java.util.*;

public class Main {
    @SuppressWarnings({"rawtypes", "unchecked"})
    static void pollute(List list) { list.add(123); }   // smuggles an Integer in

    public static void main(String[] args) {
        List<String> names = new ArrayList<>(List.of("a", "b"));
        pollute(names);                                   // heap pollution, no error yet
        System.out.println("size ok, polluted list: " + names);
        try {
            for (String s : names) System.out.print(s.length() + " ");  // hidden cast fails
        } catch (ClassCastException e) {
            System.out.println("\nfailed later, far from the cause: ClassCastException");
        }

        // Debugging aid: a checked wrapper fails at the bad insertion.
        List<String> safe = Collections.checkedList(new ArrayList<>(List.of("a", "b")), String.class);
        try {
            pollute(safe);
        } catch (ClassCastException e) {
            System.out.println("checkedList failed at the source: " + e.getMessage());
        }
    }
}

import java.lang.reflect.Array;
import java.util.*;
import java.util.function.*;

public class Main {
    static <T> T viaSupplier(Supplier<T> s) { return s.get(); }

    static <T> T viaClass(Class<T> type) throws Exception {
        return type.getDeclaredConstructor().newInstance();
    }

    static <T> T[] arrayViaFunction(int n, IntFunction<T[]> f) { return f.apply(n); }

    @SuppressWarnings("unchecked")
    static <T> T[] arrayViaReflection(Class<T> type, int n) {
        return (T[]) Array.newInstance(type, n);       // real runtime type T[]
    }

    @SuppressWarnings("unchecked")
    static <T> T[] badArray(int n) { return (T[]) new Object[n]; }  // erased to Object[]

    public static void main(String[] args) throws Exception {
        List<String> l = viaSupplier(ArrayList::new);
        System.out.println("supplier made " + l);
        System.out.println(viaClass(StringBuilder.class).append("by Class<T>"));
        String[] a = arrayViaFunction(2, String[]::new);
        String[] b = arrayViaReflection(String.class, 3);
        System.out.println("lengths " + a.length + ", " + b.length);
        try {
            String[] c = badArray(2);                  // checkcast to String[] fails
            System.out.println(c.length);
        } catch (ClassCastException e) {
            System.out.println("badArray: " + e.getMessage().substring(0, 40));
        }
    }
}

import java.lang.reflect.*;
import java.util.*;

public class Main {
    // Mini version of Jackson's TypeReference / Gson's TypeToken.
    static abstract class TypeRef<T> {
        final Type type;
        TypeRef() {
            // The anonymous subclass remembers its generic superclass in the class file.
            type = ((ParameterizedType) getClass().getGenericSuperclass()).getActualTypeArguments()[0];
        }
    }
    static class User {}

    public static void main(String[] args) {
        Type t = new TypeRef<List<User>>() {}.type;     // braces make a subclass
        System.out.println("captured: " + t.getTypeName());
        ParameterizedType p = (ParameterizedType) t;
        System.out.println("raw type: " + p.getRawType().getTypeName());
        System.out.println("element : " + p.getActualTypeArguments()[0].getTypeName());

        // A plain Class object has lost the element type.
        System.out.println("List.class prints: " + List.class.getTypeName());
    }
}

import java.util.*;

public class Main {
    // Type-safe heterogeneous container: the KEY carries the type.
    static class Favorites {
        private final Map<Class<?>, Object> map = new HashMap<>();

        <T> void put(Class<T> type, T value) {
            map.put(Objects.requireNonNull(type), type.cast(value));  // runtime check
        }
        <T> T get(Class<T> type) {
            return type.cast(map.get(type));                          // no unchecked cast
        }
    }

    @SuppressWarnings({"rawtypes", "unchecked"})
    public static void main(String[] args) {
        Favorites f = new Favorites();
        f.put(String.class, "Java");
        f.put(Integer.class, 42);
        f.put(Class.class, Favorites.class);
        String s = f.get(String.class);
        int i = f.get(Integer.class);
        System.out.println(s + " " + i + " " + f.get(Class.class).getSimpleName());

        try {
            f.put((Class) Integer.class, "not an int");  // raw abuse stopped at the source
        } catch (ClassCastException e) {
            System.out.println("raw abuse rejected by type.cast");
        }

        // Limit: List<String> and List<Integer> share one key, List.class.
        f.put(List.class, List.of("a"));
        f.put(List.class, List.of(1));
        System.out.println("only one List entry: " + f.get(List.class));
    }
}
